solutions.naive:
class Solution:
    def countSubsets(self, nums: list[int], target: int) -> int:
        ans = 0
        def dfs(i: int, total: int) -> None:
            nonlocal ans
            if i == len(nums):
                if total == target:
                    ans += 1
                return
            dfs(i + 1, total)
            dfs(i + 1, total + nums[i])
        dfs(0, 0)
        return ans

solutions.better:
class Solution:
    def countSubsets(self, nums: list[int], target: int) -> int:
        from functools import lru_cache
        @lru_cache(None)
        def dp(i: int, total: int) -> int:
            if total > target:
                return 0
            if i == len(nums):
                return 1 if total == target else 0
            return dp(i + 1, total) + dp(i + 1, total + nums[i])
        return dp(0, 0)

solutions.optimal:
class Solution:
    def countSubsets(self, nums: list[int], target: int) -> int:
        dp = [0] * (target + 1)
        dp[0] = 1
        for x in nums:
            for s in range(target, x - 1, -1):
                dp[s] += dp[s - x]
        return dp[target]

